/**
 * 负责领域行动／请求数据及执行、请求构造两种中立端口的唯一声明。
 * 输入为机器身份、允许工具、阶段和中立摘要；输出原有类型的工具、请求或验证结果。
 * 构造端口只有 create，不暴露工厂 World、事件或日次的私有状态；类型不创建请求或实现深复制。
 * 这些声明不授予资源或行动权限，期限、原体复验与提交仍归各实际所有者。
 * 保留原请求附加字段、可选性与可写数组；ActionProvider 是运行接口，不是可序列化数据。
 */
import type { ToolCall, ToolName, ActionStage, ActionWindow, Phase, MessageRef } from "@ai-werewolf-arena/game-contract";
export { TOOL_NAMES, ACTION_STAGES, DEATH_SHOT_STAGES } from "@ai-werewolf-arena/game-contract";
export type {
  ToolArgMap,
  ToolName,
  ToolCall,
  TypedToolCall,
  ToolValidationResult,
  TurnConstraints,
  ActionStage,
} from "@ai-werewolf-arena/game-contract";

import type { EntityId } from "./identity";

export interface KnightDuelSelection {
  actorId: EntityId;
  targetId: EntityId;
}
export type KnightDuelCommit = "rejected" | "continue" | "night" | "terminal";
export type SelfDestructSelection =
  | { kind: "ordinary"; actorId: EntityId; targetId: null }
  | { kind: "white_wolf_king"; actorId: EntityId; targetId: EntityId | null };

import type { ActionRequest, ActionRequestExtras } from "@ai-werewolf-arena/game-contract/requests";
export type {
  ActionRequest,
  ActionRequestContext,
  ActionRequestExtras,
} from "@ai-werewolf-arena/game-contract/requests";

export interface ActionProvider {
  getAction(request: ActionRequest): Promise<ToolCall | null>;
}

/** 工厂原八字段输入；只声明字段形状，不以目标／角色标签替代具体机制当前性校验。 */
export interface ActionRequestConstructionInput {
  phase: Phase;
  actorId: EntityId;
  /** 保留原可写数组输入；工厂在原位置复制，不把工具名称当成具体行动许可。 */
  allowedTools: ToolName[];
  stage: ActionStage;
  /** 只供原请求约束构造，不意味着本次行动已经提交或必须成功。 */
  requiresAction: boolean;
  summary: string | MessageRef;
  actionWindow?: ActionWindow;
  /** 原机制附加数据；工厂仍按原次序复制，公共日次与可见事实由其实际实现填入。 */
  context?: ActionRequestExtras;
}

/** 调用方只依赖原同步方法；调用保持所属对象 receiver，端口本身不保存 World、租约或资源。 */
export interface ActionRequestConstructionPort {
  create(input: ActionRequestConstructionInput): ActionRequest;
}

/**
 * Runs sheriff nomination, campaign, withdrawal and election voting rounds. Inputs are current
 * eligible seats, provider actions and election policy; outputs are ordered election evidence
 * and the elected sheriff. It does not apply exile ballot rules or wolf knife rules to this
 * election.
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { weddingBadgeSwallowed } from "../roles/ghost_bride/authority";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import { COMPONENT } from "../../../core/domain/components/names";
import { IdentityComponent } from "../../../core/domain/entities/player";
import {
  ActionProvider,
  EntityId,
  GameEvent,
  Phase,
  TieBreakerStrategy,
} from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { ToolGateway } from "../../gateway/tool_gateway";
import { GameActionRequestFactory } from "../../engine/action_request_factory";
import { assignSheriff, findSheriffId } from "./badge";
import { canBeSheriff, canVote } from "../common/participation";
import type { RoleCatalog } from "../roles/catalog";

export interface SheriffElectionInput {
  world: World;
  events: GameEvent[];
  toolGateway: ToolGateway;
  actionProvider: ActionProvider;
  day: number;
  enableSheriff: boolean;
  config?: ReadonlyBoardConfig;
  roleCatalog?: RoleCatalog;
  isCurrent?: () => boolean;
}

interface SheriffVote {
  actorId: EntityId;
  targetId: EntityId | null;
  abstain: boolean;
}

export async function electSheriffIfNeeded(input: SheriffElectionInput): Promise<EntityId | null> {
  if (!current(input) || weddingBadgeSwallowed(input.world)) return null;
  const { world, events, day, enableSheriff, config } = input;
  const currentSheriff = findSheriffId(world, input.roleCatalog);
  if (!enableSheriff || day !== 1 || currentSheriff !== null) return currentSheriff;

  const aliveIds = world.getAliveEntityIds().filter((id) => canVote(world, id, input.roleCatalog));
  const requests = new GameActionRequestFactory(world, events, day);
  const initialCandidates = await collectNominations(input, requests, aliveIds);
  if (!current(input)) return null;
  const candidateSet = new Set<EntityId>(initialCandidates);
  await collectCampaignSpeeches(input, requests, candidateSet);
  if (!current(input)) return null;
  const finalizedCandidates = await collectWithdrawals(input, requests, candidateSet);
  if (!current(input)) return null;
  const pk = config?.sheriff?.electionPolicy === "awa_nomination_offstage_pk_v1";
  const forbidden = pk ? new Set(initialCandidates) : candidateSet;
  let { tally, votes } =
    pk && finalizedCandidates.length === 1
      ? { tally: new Map([[finalizedCandidates[0], 0]]), votes: [] as SheriffVote[] }
      : await collectSheriffVotes(input, requests, aliveIds, finalizedCandidates, forbidden);
  if (!current(input)) return null;
  let round = 1;
  let eligible = finalizedCandidates.filter((id) => canBeSheriff(world, id, input.roleCatalog));
  const top = positiveLeaders(eligible, tally);
  if (pk && top.length > 1) {
    events.push({
      timestamp: Date.now(),
      type: "sheriff_vote_summary",
      payload: { votes, winnerId: null, round: 1 },
    });
    events.push({
      timestamp: Date.now(),
      type: "sheriff_pk_started",
      payload: { candidates: top },
    });
    await collectCampaignSpeeches(input, requests, new Set(top), "sheriff_pk_speech");
    if (!current(input)) return null;
    const tied = top.filter((id) => canBeSheriff(world, id, input.roleCatalog));
    ({ tally, votes } = await collectSheriffVotes(
      input,
      requests,
      aliveIds,
      tied,
      new Set(top),
      2,
    ));
    if (!current(input)) return null;
    eligible = tied.filter((id) => canBeSheriff(world, id, input.roleCatalog));
    round = 2;
  }
  let winner =
    pk && finalizedCandidates.length === 1 && eligible.length === 1
      ? eligible[0]
      : pickSheriffWinner(
          world,
          eligible,
          tally,
          pk ? "no_elimination" : (config?.tieBreaker?.sheriffVote ?? "min_seat"),
        );
  if (winner !== null && !assignSheriff(world, winner, config, input.roleCatalog)) winner = null;
  events.push({
    timestamp: Date.now(),
    type: "sheriff_vote_summary",
    payload: { votes, winnerId: winner, ...(pk ? { round } : {}) },
  });
  if (winner !== null) {
    events.push({
      timestamp: Date.now(),
      type: "sheriff_elected",
      payload: {
        winnerId: winner,
        candidates: finalizedCandidates,
        tally: Object.fromEntries(tally.entries()),
      },
    });
  }
  return winner;
}

async function collectNominations(
  input: SheriffElectionInput,
  requests: GameActionRequestFactory,
  aliveIds: EntityId[],
): Promise<EntityId[]> {
  const { world, events, toolGateway, actionProvider } = input;
  const candidates: EntityId[] = [];
  // 上警声明并行收集，避免顺序执行导致后手玩家读取前手“上警/退水”结果后被动调整。
  // 先建立全部请求，确保每位玩家读取同一批事件快照，再启动并行 Agent 调用。
  const nominationRequests = aliveIds
    .filter((id) => canBeSheriff(world, id, input.roleCatalog))
    .map((actorId) => ({
      actorId,
      life: captureNightLife(world, actorId),
      request: requests.create({
        phase: Phase.Day,
        actorId,
        allowedTools: ["run_for_sheriff"],
        stage: "sheriff_nomination",
        requiresAction: true,
        summary: { key: "request.summary.sheriff_nomination" },
        context: {},
      }),
    }));
  const nominationResults = await Promise.all(
    nominationRequests.map(async ({ actorId, request, life }) => {
      if (!current(input)) return null;
      const action = await actionProvider.getAction(request);
      if (
        !current(input) ||
        !life ||
        !livingNightLife(world, life) ||
        action?.name !== "run_for_sheriff"
      ) {
        return null;
      }
      const result = toolGateway.validateAndSanitize(world, actorId, action, {
        phase: Phase.Day,
      });
      if (!current(input) || !result.ok || !result.sanitizedCall) {
        return null;
      }
      return {
        actorId,
        run: result.sanitizedCall.args.run === true,
        life,
      };
    }),
  );
  if (!current(input)) return [];
  for (const item of nominationResults) {
    if (
      !item ||
      !livingNightLife(world, item.life) ||
      !canBeSheriff(world, item.actorId, input.roleCatalog)
    ) {
      continue;
    }
    events.push({
      timestamp: Date.now(),
      type: "sheriff_candidate_declared",
      payload: { actorId: item.actorId, run: item.run },
    });
    if (item.run) {
      candidates.push(item.actorId);
    }
  }

  const initialCandidates = sortBySeat(world, candidates);
  events.push({
    timestamp: Date.now(),
    type: "sheriff_nomination_summary",
    payload: { candidates: initialCandidates },
  });
  return initialCandidates;
}

async function collectCampaignSpeeches(
  input: SheriffElectionInput,
  requests: GameActionRequestFactory,
  candidateSet: Set<EntityId>,
  stage: "sheriff_campaign_speech" | "sheriff_pk_speech" = "sheriff_campaign_speech",
): Promise<void> {
  const { world, events, toolGateway, actionProvider } = input;
  const campaignOrder = sortBySeat(world, [...candidateSet]);
  // 上警发言：候选人按座位顺序发言。
  for (const candidateId of campaignOrder) {
    if (!current(input)) return;
    if (!candidateSet.has(candidateId) || !canBeSheriff(world, candidateId, input.roleCatalog)) {
      continue;
    }
    const life = captureNightLife(world, candidateId);
    if (!life) continue;
    const speechReq = requests.create({
      phase: Phase.Day,
      actorId: candidateId,
      allowedTools: ["speak"],
      stage,
      requiresAction: true,
      summary: { key: "request.summary.sheriff_campaign" },
      context: {
        sheriff_candidates: [...candidateSet],
      },
    });
    const speechAction = await actionProvider.getAction(speechReq);
    if (!current(input)) return;
    if (speechAction?.name === "speak") {
      const speechResult = toolGateway.validateAndSanitize(world, candidateId, speechAction, {
        phase: Phase.Day,
      });
      if (
        current(input) &&
        livingNightLife(world, life) &&
        speechResult.ok &&
        speechResult.sanitizedCall &&
        canBeSheriff(world, candidateId, input.roleCatalog)
      ) {
        events.push({
          timestamp: Date.now(),
          type: "day_speech",
          payload: {
            actorId: candidateId,
            text: speechResult.sanitizedCall.args.text,
          },
        });
      }
    }
  }
}

async function collectWithdrawals(
  input: SheriffElectionInput,
  requests: GameActionRequestFactory,
  candidateSet: Set<EntityId>,
): Promise<EntityId[]> {
  const { world, events, toolGateway, actionProvider } = input;
  // 发言结束后统一进入退水阶段，再进入警长投票。
  const orderedCandidates = sortBySeat(
    world,
    [...candidateSet].filter((id) => canBeSheriff(world, id, input.roleCatalog)),
  );
  const withdrawRequests = orderedCandidates.map((candidateId) => ({
    candidateId,
    life: captureNightLife(world, candidateId),
    request: requests.create({
      phase: Phase.Day,
      actorId: candidateId,
      allowedTools: ["run_for_sheriff"],
      stage: "sheriff_withdraw",
      requiresAction: true,
      summary: { key: "request.summary.sheriff_withdraw" },
      context: {
        sheriff_candidates: [...candidateSet],
      },
    }),
  }));
  const withdrawResults = await Promise.all(
    withdrawRequests.map(async ({ candidateId, request, life }) => {
      if (!current(input)) return null;
      const withdrawAction = await actionProvider.getAction(request);
      if (
        !current(input) ||
        !life ||
        !livingNightLife(world, life) ||
        withdrawAction?.name !== "run_for_sheriff"
      ) {
        return null;
      }
      const withdrawResult = toolGateway.validateAndSanitize(world, candidateId, withdrawAction, {
        phase: Phase.Day,
      });
      if (!current(input) || !withdrawResult.ok || !withdrawResult.sanitizedCall) {
        return null;
      }
      return {
        candidateId,
        keepRunning: withdrawResult.sanitizedCall.args.run === true,
        life,
      };
    }),
  );
  if (!current(input)) return [];
  const withdrawn: EntityId[] = [];
  for (const item of withdrawResults) {
    if (!item || !livingNightLife(world, item.life) || item.keepRunning) {
      continue;
    }
    candidateSet.delete(item.candidateId);
    withdrawn.push(item.candidateId);
    events.push({
      timestamp: Date.now(),
      type: "sheriff_candidate_declared",
      payload: { actorId: item.candidateId, run: false },
    });
  }
  events.push({
    timestamp: Date.now(),
    type: "sheriff_withdraw_summary",
    payload: { withdrawn: sortBySeat(world, withdrawn) },
  });

  for (const id of candidateSet)
    if (!canBeSheriff(world, id, input.roleCatalog)) candidateSet.delete(id);
  const finalizedCandidates = sortBySeat(world, [...candidateSet]);
  events.push({
    timestamp: Date.now(),
    type: "sheriff_candidates_finalized",
    payload: { candidates: finalizedCandidates },
  });
  return finalizedCandidates;
}

async function collectSheriffVotes(
  input: SheriffElectionInput,
  requests: GameActionRequestFactory,
  aliveIds: EntityId[],
  finalizedCandidates: EntityId[],
  candidateSet: Set<EntityId>,
  round = 1,
): Promise<{ tally: Map<EntityId, number>; votes: SheriffVote[] }> {
  const { world, events, toolGateway, actionProvider } = input;
  const tally = new Map<EntityId, number>();
  for (const id of finalizedCandidates) {
    tally.set(id, 0);
  }
  if (finalizedCandidates.length === 0) return { tally, votes: [] };

  // 规则：警长投票仅允许警下玩家（未在最终警上名单内）参与。
  const sheriffVoterIds = aliveIds.filter(
    (id) => !candidateSet.has(id) && canVote(world, id, input.roleCatalog),
  );
  // 警长投票同样并行收集，所有投票基于同一快照上下文。
  const candidateLives = new Map(
    finalizedCandidates.map((id) => [id, captureNightLife(world, id)]),
  );
  const sheriffVoteRequests = sheriffVoterIds.map((actorId) => ({
    actorId,
    life: captureNightLife(world, actorId),
    request: requests.create({
      phase: Phase.Day,
      actorId,
      allowedTools: ["vote_for_sheriff"],
      stage: round === 2 ? "sheriff_pk_vote" : "sheriff_vote",
      requiresAction: true,
      summary: { key: "request.summary.sheriff_vote" },
      context: {
        sheriff_candidates: finalizedCandidates,
        ...(round === 2 ? { round: 2, max_rounds: 2 } : {}),
      },
    }),
  }));
  const sheriffVoteResults = await Promise.all(
    sheriffVoteRequests.map(async ({ actorId, request, life }) => {
      if (!current(input)) return null;
      const action = await actionProvider.getAction(request);
      if (
        !current(input) ||
        !life ||
        !livingNightLife(world, life) ||
        action?.name !== "vote_for_sheriff"
      ) {
        return null;
      }
      const result = toolGateway.validateAndSanitize(world, actorId, action, {
        phase: Phase.Day,
        sheriffCandidates: finalizedCandidates,
      });
      if (!current(input) || !result.ok || !result.sanitizedCall) {
        return null;
      }

      const abstain = result.sanitizedCall.args.abstain === true;
      const targetId = result.sanitizedCall.args.target_id;
      return { actorId, targetId, abstain, life };
    }),
  );
  if (!current(input)) return { tally, votes: [] };
  const acceptedVotes: SheriffVote[] = [];
  for (const item of sheriffVoteResults) {
    if (
      !item ||
      !livingNightLife(world, item.life) ||
      !canVote(world, item.actorId, input.roleCatalog) ||
      candidateSet.has(item.actorId) ||
      (!item.abstain &&
        (item.targetId === null ||
          !finalizedCandidates.includes(item.targetId) ||
          !candidateLives.get(item.targetId) ||
          !livingNightLife(world, candidateLives.get(item.targetId)!) ||
          !canBeSheriff(world, item.targetId, input.roleCatalog)))
    ) {
      continue;
    }
    acceptedVotes.push({ actorId: item.actorId, targetId: item.targetId, abstain: item.abstain });
    events.push({
      timestamp: Date.now(),
      type: "sheriff_vote_cast",
      payload: {
        actorId: item.actorId,
        targetId: item.targetId,
        abstain: item.abstain,
      },
    });
    if (!item.abstain && item.targetId !== null) {
      tally.set(item.targetId, (tally.get(item.targetId) ?? 0) + 1);
    }
  }
  return { tally, votes: acceptedVotes };
}

function current(input: SheriffElectionInput): boolean {
  if (weddingBadgeSwallowed(input.world)) return false;
  return input.isCurrent?.() ?? true;
}

function pickSheriffWinner(
  world: World,
  candidates: EntityId[],
  tally: Map<EntityId, number>,
  strategy: TieBreakerStrategy,
): EntityId | null {
  if (candidates.length === 0) {
    return null;
  }
  const withSeat = candidates.map((id) => {
    const identity = world.getComponent(id, COMPONENT.Identity);
    return { id, seat: identity?.seat ?? id, score: tally.get(id) ?? 0 };
  });
  withSeat.sort((a, b) => {
    const diff = b.score - a.score;
    if (diff !== 0) {
      return diff;
    }
    if (strategy === "min_id") {
      return a.id - b.id;
    }
    return a.seat - b.seat;
  });
  if ((withSeat[0]?.score ?? 0) <= 0) return null;
  if (withSeat.length >= 2 && withSeat[0].score === withSeat[1].score) {
    if (strategy === "no_elimination" || strategy === "no_kill") {
      return null;
    }
  }
  return withSeat[0]?.id ?? null;
}

function sortBySeat(world: World, ids: EntityId[]): EntityId[] {
  return [...ids].sort((a, b) => {
    const aSeat = world.getComponent(a, COMPONENT.Identity)?.seat ?? a;
    const bSeat = world.getComponent(b, COMPONENT.Identity)?.seat ?? b;
    return aSeat - bSeat;
  });
}

function positiveLeaders(candidates: EntityId[], tally: Map<EntityId, number>): EntityId[] {
  const maximum = Math.max(0, ...candidates.map((id) => tally.get(id) ?? 0));
  return maximum > 0 ? candidates.filter((id) => (tally.get(id) ?? 0) === maximum) : [];
}

/**
 * Requests sheriff speaking direction and builds the resulting seat order. Inputs are current
 * seat identities, alive IDs and the validated direction; outputs preserve the default direction
 * and sheriff-last ordering. It does not assign the badge or change player life.
 */
import { COMPONENT } from "../../../core/domain/components/names";
import { IdentityComponent } from "../../../core/domain/entities/player";
import { ActionProvider, EntityId, GameEvent, Phase } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";
import { ToolGateway } from "../../gateway/tool_gateway";
import { GameActionRequestFactory } from "../../engine/action_request_factory";
import { findSheriffId } from "./badge";

export type SpeakerDirection = "clockwise" | "counter_clockwise";

export async function chooseSpeakerDirection(input: {
  world: World;
  events: GameEvent[];
  toolGateway: ToolGateway;
  actionProvider: ActionProvider;
  day: number;
  enableSheriff: boolean;
}): Promise<SpeakerDirection> {
  const { world, events, toolGateway, actionProvider, day, enableSheriff } = input;
  const defaultDirection: SpeakerDirection = "clockwise";
  if (!enableSheriff) {
    return defaultDirection;
  }

  const sheriffId = findSheriffId(world);
  if (sheriffId === null) {
    return defaultDirection;
  }

  let finalDirection: SpeakerDirection = defaultDirection;
  const requests = new GameActionRequestFactory(world, events, day);
  const req = requests.create({
    phase: Phase.Day,
    actorId: sheriffId,
    allowedTools: ["choose_direction"],
    stage: "sheriff_choose_direction",
    requiresAction: true,
    summary: { key: "request.summary.sheriff_direction" },
    context: {},
  });
  const action = await actionProvider.getAction(req);
  if (action?.name === "choose_direction") {
    const result = toolGateway.validateAndSanitize(world, sheriffId, action, {
      phase: Phase.Day,
    });
    if (result.ok && result.sanitizedCall) {
      finalDirection = result.sanitizedCall.args.direction;
    }
  }

  events.push({
    timestamp: Date.now(),
    type: "sheriff_direction_chosen",
    payload: {
      sheriffId,
      direction: finalDirection,
    },
  });

  return finalDirection;
}

export function buildSpeakerOrder(
  world: World,
  aliveIds: EntityId[],
  sheriffId: EntityId | null,
  direction: SpeakerDirection,
): EntityId[] {
  if (sheriffId === null) {
    return [...aliveIds];
  }

  const seatMap = new Map<EntityId, number>();
  for (const id of aliveIds) {
    const identity = world.getComponent(id, COMPONENT.Identity);
    seatMap.set(id, identity?.seat ?? id);
  }

  const orderedBySeat = [...aliveIds].sort((a, b) => (seatMap.get(a) ?? a) - (seatMap.get(b) ?? b));
  const sheriffIndex = orderedBySeat.indexOf(sheriffId);
  if (sheriffIndex < 0) {
    return orderedBySeat;
  }

  if (direction === "clockwise") {
    return [...orderedBySeat.slice(sheriffIndex + 1), ...orderedBySeat.slice(0, sheriffIndex + 1)];
  }

  const counterClockwise: EntityId[] = [];
  for (let i = sheriffIndex - 1; i >= 0; i--) {
    counterClockwise.push(orderedBySeat[i]);
  }
  for (let i = orderedBySeat.length - 1; i > sheriffIndex; i--) {
    counterClockwise.push(orderedBySeat[i]);
  }
  counterClockwise.push(sheriffId);
  return counterClockwise;
}

/**
 * 负责死亡警长的警徽选择请求与回复复核。输入为原警徽、死者生命、阶段／日期、当前性回调及玩家／工具入口；
 * 输出为原转移或销毁结果，警徽写入仍由警徽所有者提交。请求选择和预检不提前改变警徽。
 * 死亡许可只覆盖本次选择；持有者与许可仍当前时，已选目标生命失效按原规则改为销毁。
 * 玩家异常不被伪装成一次有效选择。
 */
import { aliveLifeVersion, type AliveComponent } from "../../../core/domain/components/alive";
import type { BadgeComponent } from "../../../core/domain/components/badge";
import type { RoleComponent } from "../../../core/domain/components/role";
import { COMPONENT } from "../../../core/domain/components/names";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import type { ActionProvider, EntityId, GameEvent, Phase } from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import { GameActionRequestFactory } from "../../engine/action_request_factory";
import type { ToolGateway } from "../../gateway/tool_gateway";
import {
  badgeSuccessorEligible,
  commitSheriffBadgeChoice,
  transferOrDestroySheriffBadge,
} from "./badge";

/** 持徽死者只在引擎打开、绑定原生命版本的临时许可内选择；这不是复活后的新生命权限。 */
export async function resolveSheriffBadge(
  world: World,
  fromId: EntityId,
  reason: string,
  events: GameEvent[],
  gateway: ToolGateway,
  provider: ActionProvider,
  phase: Phase,
  day: number,
  isCurrent: () => boolean,
): Promise<void> {
  if (!isCurrent()) return;
  const badge = world.getComponent(fromId, COMPONENT.Badge);
  if (!badge?.isSheriff || badge.destroyed) return;
  if (badge.handoffPolicy !== "awa_holder_choice_v1") {
    transferOrDestroySheriffBadge(world, fromId, reason, events);
    return;
  }
  const life = world.getComponent(fromId, COMPONENT.Alive);
  const role = world.getComponent(fromId, COMPONENT.Role);
  const version = life && aliveLifeVersion(life);
  const weight = badge.voteWeight;
  // 警徽原体、政策／权重、角色与死亡生命必须仍相同；业务阶段当前性由传入回调核对。
  const current = () =>
    isCurrent() &&
    world.getComponent(fromId, COMPONENT.Badge) === badge &&
    badge.isSheriff &&
    !badge.destroyed &&
    badge.handoffPolicy === "awa_holder_choice_v1" &&
    badge.voteWeight === weight &&
    world.getComponent(fromId, COMPONENT.Role) === role &&
    world.getComponent(fromId, COMPONENT.Alive) === life &&
    life?.alive === false &&
    aliveLifeVersion(life) === version;
  if (!life || !role || !current()) return;
  const candidates = world
    .getAliveEntityIds()
    .filter((id) => badgeSuccessorEligible(world, fromId, id));
  if (!candidates.length) {
    commitSheriffBadgeChoice(world, fromId, reason, events, null);
    return;
  }
  // 固定本次候选的原生命，不能让等待期间复活的同编号替代原接收人。
  const scopes = new Map(candidates.map((id) => [id, captureNightLife(world, id)]));
  const permit = world.openDeathAction(fromId, "choose_badge_successor", phase, day, current);
  const authorized = () =>
    current() && world.hasDeathAction(fromId, "choose_badge_successor", phase, day, permit.id);
  try {
    if (!authorized()) return;
    const request = new GameActionRequestFactory(world, events, day).create({
      phase,
      actorId: fromId,
      allowedTools: ["choose_badge_successor"],
      stage: "sheriff_badge_choice",
      requiresAction: true,
      summary: { key: "request.summary.badge_choice" },
      context: {
        allow_fallback: false,
        trigger: "badge_handoff",
        death_action_id: permit.id,
        badge_candidates: candidates,
      },
    });
    if (!authorized()) return;
    const action = await provider.getAction(request);
    if (!authorized()) return;
    let target: EntityId | null = null;
    if (action?.name === "choose_badge_successor") {
      const checked = gateway.validateAndSanitize(world, fromId, action, {
        phase,
        day,
        deathActionId: permit.id,
        badgeCandidates: candidates,
      });
      if (!authorized()) return;
      if (checked.ok && checked.sanitizedCall) target = checked.sanitizedCall.args.target_id;
    }
    // 缺失／无效选择或已失效目标保留原 null 销毁政策；玩家入口抛错则直接进入 finally，不补提交。
    if (target !== null) {
      const scope = scopes.get(target);
      if (
        !scope ||
        !livingNightLife(world, scope) ||
        !badgeSuccessorEligible(world, fromId, target)
      )
        target = null;
    }
    if (authorized()) commitSheriffBadgeChoice(world, fromId, reason, events, target);
  } finally {
    permit.close();
  }
}

/**
 * 负责从当前存活席位和 Provider 推进白天警长、普通发言与中断检查点。输入为已装配
 * World、网关和配置，输出为原发言摘要及中断结果；具体窗口构造与重入政策归规则组合。
 * 发言前后仍按原位置复查当前性与存活，窗口结果不代替死亡提交、最终阶段变化或判胜。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { createDaytimeInterruptionComposition } from "../../../rulesets/daytime-interruption-composition";
import type { DaytimeInterruptionComposition } from "../daytime-interruption-contracts";
import { AliveComponent } from "../../../core/domain/components/alive";
import { COMPONENT } from "../../../core/domain/components/names";
import {
  ActionProvider,
  ActionWindow,
  DaySummary,
  EntityId,
  GameEvent,
  Phase,
  KnightDuelWindow as DuelWindow,
} from "../../../core/domain/model";
import { RoleRegistry } from "../../../core/domain/registries/role_registry";
import { ToolGateway } from "../../gateway/tool_gateway";
import { electSheriffIfNeeded } from "../../mechanisms/sheriff/election";
import { buildSpeakerOrder, chooseSpeakerDirection } from "../../mechanisms/sheriff/speaking_order";
import { findSheriffId } from "../../mechanisms/sheriff/badge";
import { World } from "../../../core/domain/world";
import { GameActionRequestFactory } from "../action_request_factory";
import { isSelfDestructWindowEnabled } from "../../../rulesets/self-destruct-window";

/**
 * 白天流水线执行结果。
 */
export interface DayPipelineResult {
  summary: DaySummary;
  interrupted: boolean;
  selfDestruct?: import("../../../core").SelfDestructSelection;
  duel?: import("../../../core").KnightDuelSelection;
}

export interface DayPipelineOptions {
  /** 当前日次由 PhaseManager 显式传入，不能从事件历史反推。 */
  day: number;
  /** 返回 true 表示已终局，不再请求白天行动。 */
  afterSheriffElection?: () => Promise<boolean>;
  isCurrent?: () => boolean;
  commitSelfDestruct?: (
    choice: import("../../../core").SelfDestructSelection,
    window: ActionWindow,
  ) => Promise<void | boolean>;
  commitKnightDuel?: (
    choice: import("../../../core").KnightDuelSelection,
  ) => Promise<import("../../../core").KnightDuelCommit>;
}

export interface DayPipelineDependencies {
  world: World;
  roleRegistry: RoleRegistry;
  toolGateway: ToolGateway;
  events: GameEvent[];
}

/**
 * 白天阶段流水线：
 * 1) 由警长机制决定发言方向与顺序（若启用警长）。
 * 2) 按顺序串行发言并写入事件流。
 * 3) 在可配置窗口中允许自爆中断流程。
 */
export class DayPipeline {
  private readonly world: World;
  private readonly roleRegistry: RoleRegistry;
  private readonly toolGateway: ToolGateway;
  private readonly events: GameEvent[];
  private readonly interruptions: DaytimeInterruptionComposition;
  constructor(dependencies: DayPipelineDependencies) {
    this.world = dependencies.world;
    this.roleRegistry = dependencies.roleRegistry;
    this.toolGateway = dependencies.toolGateway;
    this.events = dependencies.events;
    this.interruptions = createDaytimeInterruptionComposition({
      world: () => this.world,
      roleRegistry: () => this.roleRegistry,
      toolGateway: () => this.toolGateway,
      events: () => this.events,
    });
  }

  async execute(
    config: ReadonlyBoardConfig,
    actionProvider: ActionProvider,
    options: DayPipelineOptions,
  ): Promise<DayPipelineResult> {
    this.interruptions.assertEntry();
    const speeches: DaySummary["speeches"] = [];
    const requests = new GameActionRequestFactory(this.world, this.events, options.day);
    const isCurrent = options.isCurrent ?? (() => true);
    if (!isCurrent()) return { summary: { speeches, selfDestructBy: null }, interrupted: false };
    if (
      options.day === 1 &&
      config.enableSheriff &&
      findSheriffId(this.world) === null &&
      config.hooks.onPreElection &&
      isSelfDestructWindowEnabled(config, ActionWindow.OnPreElection)
    ) {
      const exploded = await this.interruptions.selfDestruct.execute(
        requests,
        actionProvider,
        ActionWindow.OnPreElection,
        Phase.Day,
        isCurrent,
        (id) => options.commitSelfDestruct?.(id, ActionWindow.OnPreElection) ?? Promise.resolve(),
      );
      if (exploded !== null)
        return {
          summary: { speeches, selfDestructBy: exploded.actorId },
          interrupted: true,
          selfDestruct: exploded,
        };
      if (!isCurrent()) return { summary: { speeches, selfDestructBy: null }, interrupted: false };
    }
    await electSheriffIfNeeded({
      world: this.world,
      events: this.events,
      toolGateway: this.toolGateway,
      actionProvider,
      day: options.day,
      enableSheriff: config.enableSheriff,
      config,
      isCurrent,
    });
    if (!isCurrent()) return { summary: { speeches, selfDestructBy: null }, interrupted: false };
    if (await options.afterSheriffElection?.()) {
      return {
        summary: { speeches, selfDestructBy: null },
        interrupted: false,
      };
    }

    if (config.hooks.onDaybreak && isSelfDestructWindowEnabled(config, ActionWindow.OnDaybreak)) {
      const exploded = await this.interruptions.selfDestruct.execute(
        requests,
        actionProvider,
        ActionWindow.OnDaybreak,
        Phase.Day,
        isCurrent,
        (id) => options.commitSelfDestruct?.(id, ActionWindow.OnDaybreak) ?? Promise.resolve(),
      );
      if (exploded !== null) {
        return {
          summary: {
            speeches,
            selfDestructBy: exploded.actorId,
          },
          interrupted: true,
          selfDestruct: exploded,
        };
      }
    }

    if (!isCurrent()) return { summary: { speeches, selfDestructBy: null }, interrupted: false };
    const openingDuel = await this.interruptions.duel.execute(
      config,
      requests,
      actionProvider,
      DuelWindow.BeforeSpeeches,
      isCurrent,
      options.commitKnightDuel,
    );
    if (openingDuel.endsDay)
      return {
        summary: { speeches, selfDestructBy: null },
        interrupted: true,
        ...(openingDuel.selection ? { duel: openingDuel.selection } : {}),
      };
    if (!isCurrent()) return { summary: { speeches, selfDestructBy: null }, interrupted: false };
    const speakerDirection = await chooseSpeakerDirection({
      world: this.world,
      events: this.events,
      toolGateway: this.toolGateway,
      actionProvider,
      day: options.day,
      enableSheriff: config.enableSheriff,
    });

    const speakers = buildSpeakerOrder(
      this.world,
      this.world.getAliveEntityIds(),
      findSheriffId(this.world),
      speakerDirection,
    );

    for (const actorId of speakers) {
      if (!isCurrent()) return { summary: { speeches, selfDestructBy: null }, interrupted: false };
      if (!this.isAlive(actorId)) {
        continue;
      }

      // 辩论可能令原演员出局或跳过发言；返回后仍复查，不跳过该席位的后续间隙。
      const debate = await this.interruptions.debate.execute(
        config,
        requests,
        actionProvider,
        actorId,
        options.day,
        isCurrent,
      );
      if (!isCurrent()) return { summary: { speeches, selfDestructBy: null }, interrupted: false };
      if (!debate.skipSpeech && this.isAlive(actorId)) {
        const req = requests.create({
          phase: Phase.Day,
          actorId,
          allowedTools: ["speak"],
          stage: "day_speech",
          requiresAction: true,
          summary: { key: "request.summary.day_speech" },
          context: {},
        });

        const action = await actionProvider.getAction(req);
        if (!isCurrent())
          return { summary: { speeches, selfDestructBy: null }, interrupted: false };
        if (action?.name === "speak") {
          const result = this.toolGateway.validateAndSanitize(this.world, actorId, action, {
            phase: Phase.Day,
          });

          if (result.ok && result.sanitizedCall) {
            speeches.push({ actorId, text: result.sanitizedCall.args.text });
            this.events.push({
              timestamp: Date.now(),
              type: "day_speech",
              payload: {
                actorId,
                text: result.sanitizedCall.args.text,
              },
            });
          }
        }
      }

      if (
        config.hooks.onPerSpeechGap &&
        isSelfDestructWindowEnabled(config, ActionWindow.OnPerSpeechGap)
      ) {
        const exploded = await this.interruptions.selfDestruct.execute(
          requests,
          actionProvider,
          ActionWindow.OnPerSpeechGap,
          Phase.Day,
          isCurrent,
          (id) =>
            options.commitSelfDestruct?.(id, ActionWindow.OnPerSpeechGap) ?? Promise.resolve(),
        );
        if (exploded !== null) {
          return {
            summary: {
              speeches,
              selfDestructBy: exploded.actorId,
            },
            interrupted: true,
            selfDestruct: exploded,
          };
        }
      }
      const gapDuel = await this.interruptions.duel.execute(
        config,
        requests,
        actionProvider,
        DuelWindow.BetweenSpeeches,
        isCurrent,
        options.commitKnightDuel,
      );
      if (gapDuel.endsDay)
        return {
          summary: { speeches, selfDestructBy: null },
          interrupted: true,
          ...(gapDuel.selection ? { duel: gapDuel.selection } : {}),
        };
    }

    const closingDuel = await this.interruptions.duel.execute(
      config,
      requests,
      actionProvider,
      DuelWindow.AfterSpeeches,
      isCurrent,
      options.commitKnightDuel,
    );
    if (closingDuel.endsDay)
      return {
        summary: { speeches, selfDestructBy: null },
        interrupted: true,
        ...(closingDuel.selection ? { duel: closingDuel.selection } : {}),
      };

    return {
      summary: {
        speeches,
        selfDestructBy: null,
      },
      interrupted: false,
    };
  }

  /**
   * 判断目标玩家是否存活。
   */
  private isAlive(entityId: EntityId): boolean {
    const alive = this.world.getComponent(entityId, COMPONENT.Alive);
    return alive?.alive === true;
  }
}

/**
 * 负责有序死亡波、角色死亡钩子、枪击选择、遗言与警徽交接。输入是待处理的死亡名单、
 * 原死因与原生命行动权限；输出是按原顺序提交的死亡、事件和内部关联凭证。实际生命修改和唯一已结算
 * 账本委托 DeathCommitter，双生、动物、婚约及狼美人关系事实归具体贡献；已提交整波在梦／遗言前交角色扩展，
 * 野孩子贡献自行核对榜样原生命。参数仍使用同一深只读规则视图，不建立第二份角色状态。
 * 初始关系扩张／阶段登记／双生准备归具名规则组合；本结算器仍在原标死之后提交／发布双生回执。
 * 未提交预约只在已进入的原 finally 处取消，已提交回执不因后续发布失败而回滚。
 * 枪的资格归共同所有者，请求、等待与目标复验归规则组合；本结算器持同一许可数组并在原时点关闭。
 * 本模块不切换阶段或确定最终胜负；关系扩展、遗言、警徽和枪的最终过期保留原执行顺序。
 */
import { refreshWolfKnifeInheritanceAtCheckpoint } from "../../rulesets/wolf-knife-inheritance-plan";
import { AnimalDeathWavePreparation } from "../mechanisms/roles/animal_dream/ports";
import {
  planDeathWave,
  openDeathWave,
  deathExecutionContext,
  type DeathExecutionContext,
  deathWaveOriginalLives,
  deathWavePoisonMetadata,
  type DeathWaveUnit,
  preflightDeathWaveData,
  DeathCommitReceipt,
  type DeathOriginalLife,
} from "./death-wave";
import type { NightPoisonRoute } from "../../core/domain/night_effects";
import { DeathCommitter } from "./death-committer";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { FRAGRANT_PAIR_POLICY } from "@ai-werewolf-arena/game-contract/facts/fragrant-pair-seer";
import {
