  actorId: number,
  tool: ActionRequest["allowedTools"][number],
  stage: ActionRequest["context"]["stage"],
): ActionRequest {
  return {
    actorId,
    phase: tool === "vote" ? Phase.Voting : Phase.Day,
    allowedTools: [tool],
